dtsPropsFor.BrandSymbol:
/** Rendered width & height in px. Default 240. */
size?: number;
/** Rotate the graphite circle continuously. Default true. */
animateRotation?: boolean;
/** Seconds per full rotation. Default 60. */
rotationDuration?: number;
/** Pulse the olive center dot. Default true. */
pulseDot?: boolean;
className?: string;
/** Accessible label for the SVG. Default "Símbolo NP Hub". */
ariaLabel?: string;

dtsPropsFor.BrandSymbolBuild:
/** Rendered width & height in px. Default 180. */
size?: number;
className?: string;

dtsPropsFor.MagneticButton:
/** Pointer-follow strength, 0–1. Default 0.35. */
strength?: number;
className?: string;
children?: React.ReactNode;
type?: "button" | "submit" | "reset";
disabled?: boolean;
onClick?: React.MouseEventHandler<HTMLButtonElement>;

dtsPropsFor.EditorialHeader:
/** Left-hand editorial credit, e.g. "NP HUB — MÉTODO". */
edition: string;
/** Right-hand index label, e.g. "Nº 001". */
index: string;

dtsPropsFor.WordReveal:
/** Text revealed word by word on mount. */
text: string;
className?: string;
/** Class applied to each animated word span. */
wordClassName?: string;
/** Delay before the first word, in seconds. Default 0. */
delay?: number;
/** Per-word stagger, in seconds. Default 0.08. */
stagger?: number;
/** Element tag to render. Default "span". */
as?: "h1" | "h2" | "h3" | "p" | "span";
/** Map of lowercase word → extra className, to accent specific words. */
highlights?: Record<string, string>;
